'use strict';
const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const reducedQuery=window.matchMedia('(prefers-reduced-motion: reduce)');
let paused=reducedQuery.matches, lenis=null, heroPaused=false;
const hasMotion=typeof gsap!=='undefined';
if(hasMotion){gsap.registerPlugin(ScrollTrigger);if(!paused&&window.matchMedia('(pointer:fine)').matches&&typeof Lenis!=='undefined'){lenis=new Lenis({duration:1.05,smoothWheel:true,anchors:true});lenis.on('scroll',ScrollTrigger.update);gsap.ticker.add(t=>lenis?.raf(t*1000));gsap.ticker.lagSmoothing(0);}}
const characters=[
{name:'The One Above',role:'Sovereignty / The sun',image:'the-one-above.jpeg',epithet:'Power is a burden before it is a gift.',description:'The central figure of the ten. Forged by hardship, failure, and sacrifice, he understands the distance between possessing power and deserving it. His presence is immense. The responsibility he carries is greater.',question:'Can a leader protect humanity without taking away its freedom?',detail:'His story begins in struggle, not privilege. A life shaped by necessity, imprisonment, and devotion to family gives his authority a human foundation. He is not a flawless savior. He is a man whose failures have taught him the cost of every decision. The sun and the satellites around him give visual form to his place at the center of this universe.'},
{name:'Anacaona',role:'Abundance / The living world',image:'anacaona.jpeg',epithet:'A civilization is only as rich as what it allows to flourish.',description:'The Golden Flower. Anacaona embodies abundance, love, and the relationship between people and their environment. Her strength is generative: the power to nurture what a civilization needs to survive.',question:'What is the value of progress if the living world pays its price?',detail:'Inspired by the spirit of the historical Taíno queen, this fictional character brings a distinct cultural presence to the ten. Her perspective is rooted in flourishing rather than accumulation. The natural world is not a resource standing outside humanity; it is the foundation of humanity’s future.'},
{name:'Bahar',role:'Consciousness / The inner world',image:'bahar.jpeg',epithet:'The longest journey takes place within.',description:'Bahar brings the inner world into focus. Among beings able to traverse the universe, she represents the mystery that remains inside the mind: awareness, perception, and the experience of being alive.',question:'How much can we understand another life without first understanding our own?',detail:'Bahar’s place in the universe centers on consciousness and interior experience. Her perspective turns the story inward, toward the emotional and perceptual dimensions of existence. In an ensemble of extraordinary capabilities, she keeps attention on the lived experience of the individual.'},
{name:'Solomon',role:'Wisdom / Equilibrium',image:'solomon.jpeg',epithet:'Truth has no need for a throne.',description:'The Inevitable One. Counselor, ambassador, and judge, Solomon seeks the balance between chaos and order. His authority comes from discernment rather than wealth or spectacle.',question:'When every side believes it is right, what does justice require?',detail:'Solomon offers a measured presence within the ten. He listens, weighs, and challenges easy answers. His wisdom does not remove conflict; it gives conflict a language through which understanding might become possible. The exposed mind and meditative posture of his design make thought itself monumental.'},
{name:'RhiAna',role:'Resonance / Music',image:'rhiana.jpeg',epithet:'Some truths can only be felt.',description:'RhiAna carries the language of resonance. Music, vibration, and healing meet in a figure whose influence reaches beyond speech. She gives harmony both an emotional and a physical presence.',question:'Can harmony exist without asking every voice to become the same?',detail:'Her visual design translates sound into gesture, notation, and rhythm. The multiple arms and musical motifs suggest a consciousness moving across many frequencies at once. In the story’s human conflicts, her presence opens a path toward connection that argument alone cannot create.'},
{name:'Al Nabarr',role:'Conquest / Unity',image:'al-nabarr.jpeg',epithet:'Unity has a price. Who is asked to pay it?',description:'Al Nabarr embodies the tension between conquest and unity. His formidable presence raises one of the story’s hardest questions: whether peace imposed by strength can ever become a peace freely chosen.',question:'Is a united world still united when it has no choice?',detail:'The current visual direction draws on a Mali-inspired identity: a dark-skinned Black man in layered robes, a turban, and tactical elements. His design combines cultural specificity with the authority of a cosmic commander. Through him, the promise of order confronts the moral cost of domination.'},
{name:'Luna',role:'The moon / Cycles',image:'luna.jpeg',epithet:'Every ending belongs to a larger rhythm.',description:'Luna reflects the cycles of the moon: change, tides, reflection, and return. She brings attention to patterns that outlast individuals and to the quiet forces that shape entire worlds.',question:'Can we recognize a cycle early enough to change its course?',detail:'Her current visual identity is Moroccan, with curls, a crescent headdress, and orbiting lunar forms. The design makes her relationship to rhythm and celestial cycles tangible. In a story about civilizations repeating themselves, Luna holds a particularly intimate relationship with recurrence.'},
{name:'Arkem',role:'Chemistry / Healing',image:'arkem.jpeg',epithet:'To transform life, first understand its composition.',description:'Arkem is the physician and the chemist. He understands existence through its smallest interactions: the elements and reactions that can restore a body, alter a mind, or change the conditions of life.',question:'When the power to heal becomes the power to alter, where is the boundary?',detail:'The current character is male, with a Hendrix-inspired presence, an expressive afro, and purple molecular imagery. His science is personal and physical. Arkem’s perspective connects the universe’s immense scale to the intimate complexity of the human body.'},
{name:'Meiyoshin',role:'Honor / Guardianship',image:'meiyoshin.jpeg',epithet:'Strength finds its meaning in what it protects.',description:'Meiyoshin carries the discipline of a warrior and the responsibility of a guardian. Honor gives direction to his power; the people and principles entrusted to him give it purpose.',question:'What happens when duty and conscience point in opposite directions?',detail:'His Japanese warrior design draws on the kabuto, a masked face, and the presence of swords. Restraint matters as much as force. Among the ten, his perspective brings loyalty, protection, and the difficult obligations of service into sharp focus.'},
{name:'Kephra',role:'Probability / Possibility',image:'kephra.jpeg',epithet:'No future is the only future.',description:'Kephra represents possibility: the branching paths that sit behind every choice. She brings uncertainty into a group whose extraordinary knowledge might otherwise resemble certainty.',question:'If you could see what might happen, could you still choose freely?',detail:'Her role centers on probability and the existence of multiple possible outcomes. She gives the story a living relationship with the future, where knowledge does not automatically produce agreement. Her black niqab, flowing ceremonial fabric, and precise tactical details preserve a powerful human presence. The geometric structure above her palm gives visible form to potential becoming reality.'}
];
let selected=0;
const tabs=$('#character-tabs');
characters.forEach((c,i)=>{const b=document.createElement('button');b.className='character-tab';b.id=`character-tab-${i}`;b.setAttribute('role','tab');b.setAttribute('aria-controls','character-panel');b.setAttribute('aria-label',c.name);b.innerHTML=`<span class="tab-portrait ${c.image?'':'tab-number'}">${c.image?`<img src="assets/${c.image}" alt="" loading="lazy" width="102" height="153">`:'10'}</span><span>${String(i+1).padStart(2,'0')} / ${c.name}</span>`;b.addEventListener('click',()=>selectCharacter(i));b.addEventListener('keydown',e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%10;else if(e.key==='ArrowLeft')n=(i+9)%10;else if(e.key==='Home')n=0;else if(e.key==='End')n=9;else return;e.preventDefault();selectCharacter(n);$(`#character-tab-${n}`).focus();});tabs.append(b);});
function selectCharacter(i){selected=(i+characters.length)%characters.length;const c=characters[selected];$('#character-index').textContent=`${String(selected+1).padStart(2,'0')} / 10`;$('#character-name').textContent=c.name;$('#character-role').textContent=c.role;$('#character-epithet').textContent=c.epithet;$('#character-description').textContent=c.description;$('#character-question').textContent=c.question;const img=$('#character-image');img.hidden=!c.image;$('#character-unseen').hidden=!!c.image;if(c.image){img.src=`assets/${c.image}`;img.alt=`${c.name} — original illustrated character design`;}window.sceneMotion?.selectCharacter(c.image.replace('.jpeg',''));$('#character-panel').setAttribute('aria-labelledby',`character-tab-${selected}`);$$('.character-tab').forEach((el,j)=>{el.setAttribute('aria-selected',String(j===selected));el.tabIndex=j===selected?0:-1;});if(hasMotion&&!paused)gsap.fromTo([$('#character-unseen'),$('#character-name'),$('#character-epithet'),$('#character-description')],{opacity:.15,y:9},{opacity:1,y:0,duration:.45,stagger:.02,overwrite:true});}
selectCharacter(0);
$('#character-prev').addEventListener('click',()=>selectCharacter(selected-1));$('#character-next').addEventListener('click',()=>selectCharacter(selected+1));
let lastFocus=null;
function openDialog(id){lastFocus=document.activeElement;const d=$('#'+id);d.showModal();document.body.classList.add('locked');lenis?.stop();d.scrollTop=0;}
$$('[data-dialog]').forEach(el=>el.addEventListener('click',()=>openDialog(el.dataset.dialog)));
$$('dialog').forEach(d=>{$('.dialog-close',d).addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{document.body.classList.remove('locked');if(!paused)lenis?.start();lastFocus?.focus({preventScroll:true});});});
$('#character-dossier').addEventListener('click',()=>{const c=characters[selected];$('#dossier-label').textContent=`${String(selected+1).padStart(2,'0')} / ${c.role}`;$('#dossier-title').textContent=c.name;$('#dossier-epithet').textContent=c.epithet;$('#dossier-copy').textContent=c.detail;$('#dossier-question').textContent=c.question;openDialog('dossier-dialog');});
const menu=$('#navigation'), menuButton=$('.menu-toggle');
function toggleMenu(force){const open=typeof force==='boolean'?force:menu.hidden;menu.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open);document.body.classList.toggle('locked',open);if(open){lenis?.stop();$('a',menu).focus();}else{if(!paused)lenis?.start();menuButton.focus({preventScroll:true});}}
menuButton.addEventListener('click',()=>toggleMenu());$$('a',menu).forEach(a=>a.addEventListener('click',()=>toggleMenu(false)));
document.addEventListener('keydown',e=>{if(!menu.hidden&&e.key==='Escape')toggleMenu(false);if(!menu.hidden&&e.key==='Tab'){const focusables=[menuButton,...$$('a',menu)],first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
if(hasMotion){if(!paused){gsap.from('.intro-item',{y:35,opacity:0,duration:1.25,stagger:.11,ease:'power3.out',delay:.12});gsap.from('.hero-figure',{opacity:0,duration:1.6,delay:.2});$$('.reveal').forEach(el=>gsap.from(el,{y:35,opacity:0,duration:1,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 93%',once:true}}));gsap.to('.origin-media',{yPercent:8,ease:'none',scrollTrigger:{trigger:'.origin',start:'top bottom',end:'bottom top',scrub:1}});}}
const chronicle=$('.chronicle');let chapterIndex=-1,scrollQueued=false;
function updateScroll(){scrollQueued=false;const scroll=window.scrollY,max=document.documentElement.scrollHeight-window.innerHeight;$('.reading-progress').style.transform=`scaleX(${max>0?scroll/max:0})`;const r=chronicle.getBoundingClientRect(),range=chronicle.offsetHeight-window.innerHeight;const progress=Math.max(0,Math.min(.9999,-r.top/Math.max(1,range)));const idx=Math.min(2,Math.floor(progress*3));if(idx!==chapterIndex){chapterIndex=idx;$$('.chapter').forEach((c,i)=>c.classList.toggle('active',i===idx));$$('.chapter-track span').forEach((c,i)=>c.classList.toggle('active',i<=idx));$('.chapter-number').textContent=String(idx+1).padStart(2,'0');$('.chapter-counter').textContent=`${String(idx+1).padStart(2,'0')} — 03`;}if(!paused)$('.cosmic-rings').style.transform=`rotate(${-35+progress*145}deg)`;}
window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateScroll);}},{passive:true});window.addEventListener('resize',updateScroll);updateScroll();
function syncMotion(){document.body.classList.toggle('motion-paused',paused);const b=$('.motion-toggle');b.setAttribute('aria-pressed',String(paused));const motionMode=heroPaused?'off':paused?'reduced':'full';window.heroMotion?.setMode(motionMode);window.sceneMotion?.setEnabled(!paused);b.innerHTML=`<span aria-hidden="true">${paused?'▷':'Ⅱ'}</span> Motion ${motionMode==='full'?'on':motionMode}`;b.title=paused?'Enable full motion':'Pause motion';if(paused){lenis?.destroy();lenis=null;if(hasMotion){gsap.set('.reveal',{opacity:1,y:0});ScrollTrigger.getAll().forEach(s=>{if(s.trigger?.classList.contains('origin'))s.disable(false);});}}else{lenis?.start();if(hasMotion)ScrollTrigger.getAll().forEach(s=>s.enable(false));}}
$('.motion-toggle').addEventListener('click',()=>{paused=!paused;heroPaused=paused;syncMotion();});reducedQuery.addEventListener('change',e=>{paused=e.matches;heroPaused=false;syncMotion();});syncMotion();
window.addEventListener('load',()=>{if(hasMotion)ScrollTrigger.refresh();updateScroll();});
